class Solution {
public:
    int peakValleyDifference(vector<int>& nums) {
        long long ans = 0;
        int n = nums.size();
        for (int i = 1; i + 1 < n; ++i) {
            if (nums[i] > nums[i - 1] && nums[i] > nums[i + 1]) {
                ans += nums[i];
            } else if (nums[i] < nums[i - 1] && nums[i] < nums[i + 1]) {
                ans -= nums[i];
            }
        }
        return static_cast<int>(ans);
    }
};
